["Tests/TestSocketIO/SocketTimedEmitterTest.swift","e695a6efc50820e26791d6176c99461c538bff36ceea3c8047b7b6afc705ca5d","9bbc44101e6d8c004b4244ca2eca1620348a34c2745036289eacad02a2884af5",[[266,266,"        let expectedID = manager.handleQueue.sync { socket.currentAck + 1 }\n"],[279,280,"        guard await waitForTimedAckRegistration(expectedID) else {\n            task.cancel()\n            return\n        }\n"],[312,312,"    /// Observe the actual registration on its owning queue, with a bounded wait.\n    private func waitForTimedAckRegistration(_ id: Int) async -> Bool {\n        let socket = self.socket!\n        let queue = manager.handleQueue\n        let deadline = DispatchTime.now() + .seconds(5)\n        while DispatchTime.now() < deadline {\n            let registered: Bool = await withCheckedContinuation { continuation in\n                queue.async {\n                    continuation.resume(returning: socket.ackHandlers.pendingTimedAckIDs.contains(id))\n                }\n            }\n            if registered { return true }\n            await Task.yield()\n        }\n        XCTFail(\"Acknowledgement \\(id) was not registered\")\n        return false\n    }\n\n"],[318,318,"        let expectedID = manager.handleQueue.sync { socket.currentAck + 1 }\n"],[327,329,"        guard await waitForTimedAckRegistration(expectedID) else {\n            task.cancel()\n            return\n        }\n        manager.handleQueue.async { socket.didDisconnect(reason: \"test\") }\n"],[338,338,"        let expectedID = manager.handleQueue.sync { socket.currentAck + 1 }\n"],[346,348,"        guard await waitForTimedAckRegistration(expectedID) else {\n            task.cancel()\n            return\n        }\n        manager.handleQueue.async { socket.didDisconnect(reason: \"test\") }\n"],[360,360,"        let expectedID = manager.handleQueue.sync { socket.currentAck + 1 }\n"],[362,364,"        guard await waitForTimedAckRegistration(expectedID) else {\n            task.cancel()\n            return\n        }\n        manager.handleQueue.async { socket.handleAck(expectedID, data: [123]) }\n"],[375,375,"        let expectedID = manager.handleQueue.sync { socket.currentAck + 1 }\n"],[376,378,"        guard await waitForTimedAckRegistration(expectedID) else {\n            task.cancel()\n            return\n        }\n        manager.handleQueue.async { socket.handleAck(expectedID, data: [42]) }\n"]]],
